package org.rabochaya.projects;
import android.graphics.*;import java.io.*;import java.util.*;
/** Explicit PNG/JPEG/BMP/static-GIF pair, read only; bounded regional or indexed decoding. */
public final class OziRaster implements Closeable,RasterMapImport.Source {
 public static final long MAX_IMAGE=512L*1024*1024;public final OziCalibration calibration;private final BitmapRegionDecoder decoder;private final BmpRaster bitmap;private final GifRaster gifRaster;private final LinkedHashMap<Long,Bitmap> tiles=new LinkedHashMap<>(16,.75f,true);private long bytes;private boolean closed;
 public OziRaster(File map,File image,String selectedName)throws IOException{this(map,image,selectedName,OziCalibration.Encoding.UTF8);}
 public OziRaster(File map,File image,String selectedName,OziCalibration.Encoding encoding)throws IOException{
  if(!map.isFile()||map.length()>OziCalibration.MAX_BYTES||!image.isFile()||image.length()>MAX_IMAGE)throw new IOException("Ozi: предел .map 128 КиБ, изображения 512 МиБ");
  byte[] signature=new byte[8];try(DataInputStream in=new DataInputStream(new FileInputStream(image))){in.readFully(signature);}boolean png=Arrays.equals(signature,new byte[]{(byte)137,80,78,71,13,10,26,10}),jpeg=(signature[0]&255)==255&&(signature[1]&255)==216&&(signature[2]&255)==255,bmp=signature[0]==66&&signature[1]==77,gif=signature[0]==71&&signature[1]==73&&signature[2]==70;if(!png&&!jpeg&&!bmp&&!gif)throw new IOException("Ozi: поддержаны PNG/JPEG/raw BMP24/32 или один статический GIF");
  BitmapRegionDecoder opened=null;BmpRaster raw=null;GifRaster small=null;try{int w,h;if(gif){small=GifRaster.read(image);w=small.width;h=small.height;}else if(bmp){raw=new BmpRaster(image);w=raw.width;h=raw.height;}else{opened=BitmapRegionDecoder.newInstance(image.getPath(),false);if(opened==null)throw new IOException("Ozi: изображение не декодировано");w=opened.getWidth();h=opened.getHeight();}if(w<1||h<1||w>20000||h>20000||(long)w*h>100000000)throw new IOException("Ozi: предел 20 000 по стороне / 100 млн пикселей");try(InputStream in=new FileInputStream(map)){calibration=OziCalibration.read(in,selectedName,w,h,encoding);}decoder=opened;bitmap=raw;gifRaster=small;}catch(IOException|RuntimeException e){if(opened!=null)opened.recycle();if(small!=null)small.close();if(raw!=null)try{raw.close();}catch(IOException ignored){}if(e instanceof IOException)throw (IOException)e;throw new IOException("Ozi: ошибка изображения/привязки",e);}

 }
 public GeoRasterTransform transform(){return calibration.transform;}
 public synchronized int color(double lon,double lat)throws IOException{if(closed)throw new IOException("Ozi reader закрыт");long cell=transform().cell(lon,lat);if(cell<0)return 0;int x=(int)cell,y=(int)(cell>>>32);if(bitmap!=null)return bitmap.pixel(x,y);if(gifRaster!=null)return gifRaster.pixel(x,y);int tx=x/256,ty=y/256;long key=(long)ty<<32|tx;Bitmap tile=tiles.get(key);if(tile==null){BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.ARGB_8888;options.inScaled=false;int left=tx*256,top=ty*256;try{tile=decoder.decodeRegion(new Rect(left,top,Math.min(left+256,transform().width),Math.min(top+256,transform().height)),options);}catch(RuntimeException e){throw new IOException("Ozi: ошибка чтения региона",e);}if(tile==null)throw new IOException("Ozi: пустой регион изображения");long size=tile.getByteCount();while(!tiles.isEmpty()&&(tiles.size()>=64||bytes+size>16L*1024*1024)){Iterator<Map.Entry<Long,Bitmap>> it=tiles.entrySet().iterator();Bitmap old=it.next().getValue();it.remove();bytes-=old.getByteCount();old.recycle();}tiles.put(key,tile);bytes+=size;}return tile.getPixel(x%256,y%256);}
 public synchronized void close()throws IOException{if(closed)return;closed=true;for(Bitmap tile:tiles.values())tile.recycle();tiles.clear();bytes=0;if(decoder!=null)decoder.recycle();if(bitmap!=null)bitmap.close();if(gifRaster!=null)gifRaster.close();}
}
